from itertools import permutations

def calculate_sign(p):
    """Calculates the sign of a permutation p (represented as a tuple)."""
    # Number of inversions
    n = len(p)
    inversions = 0
    for i in range(n):
        for j in range(i + 1, n):
            if p[i] > p[j]:
                inversions += 1

    # Sign is (-1)^number_of_inversions
    return 1 if inversions % 2 == 0 else -1

def count_signed_derangements(N):
    """Counts the sum of signs for all derangements of size N."""
    total_signed_count = 0

    # Iterate through all permutations of {1, 2, ..., N}
    for p in permutations(range(1, N + 1)):
        # Check if it is a derangement (no fixed points)
        is_derangement = True
        for i in range(N):
            # p[i] is the image of i+1. Fixed point if p[i] == i+1
            if p[i] == i + 1:
                is_derangement = False
                break

        if is_derangement:
            sign = calculate_sign(p)
            total_signed_count += sign

    return total_signed_count

# Calculate for N=4 and N=5
d4 = count_signed_derangements(4)
d5 = count_signed_derangements(5)

print(f"d_4 (Sum of signs of derangements of 4): {d4}")
print(f"d_5 (Sum of signs of derangements of 5): {d5}")

